// Isolation test (OS-12) — construct ReachabilityGate with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21, MF-22.)
import { describe, expect, it } from "vitest";
import { asProjection, height } from "../src/kernel/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import { ReachabilityGate, type ReachabilityEvaluation, type ReachabilityProjections } from "../src/reachability/index.js";

const u = "u1" as Unit;
const c0 = "c0" as Currency;
const c1 = "c1" as Currency;
const at = height(1);

/** OBJ-24 stand-ins answering a fixed evaluation. */
const answering = (evaluation: ReachabilityEvaluation): ReachabilityProjections => ({
  of: () => asProjection("Reachability", () => evaluation),
});
const reachable: ReachabilityEvaluation = { verdict: "reachable", unit: u, currency: c1, at, witnesses: [] };
const unreachable: ReachabilityEvaluation = { verdict: "unreachable", unit: u, currency: c1, at, witnesses: [], cheapestUnmet: c0 };

describe("ReachabilityGate in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new ReachabilityGate({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new ReachabilityGate({ reachability: {} as never })).toThrow();
  });

  it("evaluate answers differently when reachability differs", () => {
    const a = new ReachabilityGate({ reachability: answering(reachable) }).evaluate(u, c1, at);
    const b = new ReachabilityGate({ reachability: answering(unreachable) }).evaluate(u, c1, at);
    expect(a).not.toEqual(b);
  });

  it("admit answers differently when reachability differs", () => {
    const a = new ReachabilityGate({ reachability: answering(reachable) }).admit(u, c1, at);
    const b = new ReachabilityGate({ reachability: answering(unreachable) }).admit(u, c1, at);
    expect(a).not.toEqual(b);
  });
});
